customCodeBlocks.code:
@theme {
  --color-sumi: #1a1613;
  --color-paper: #f4ecdd;
  --color-sakura: #f2b8c6;
  --color-deep-sakura: #d9748f;
  --color-vermilion: #c8412b;
  --color-gold: #b8923a;
  --color-indigo: #2b3a55;
  --font-display: var(--font-shippori), serif;
  --font-body: var(--font-zen), sans-serif;
  --font-mono: var(--font-dm-mono), monospace;
}
* {
  box-sizing: border-box;
}
body.am-body {
  margin: 0;
  background: var(--am-paper);
  color: var(--am-ink);
  font-family: var(--font-body);
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input {
  font: inherit;
}
.am-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  letter-spacing: 0.08em;
  font-size: 1.05rem;
}
.am-hanko {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--am-red);
  color: var(--am-red);
  font: 500 0.62rem var(--font-mono);
  letter-spacing: -0.12em;
}
.am-header nav {
  display: flex;
  gap: 24px;
  margin-left: auto;
  font: 500 0.65rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.12em;
}
.am-header nav a {
  position: relative;
  padding-bottom: 3px;
}
.am-header nav a::after {
  content: "";
  position: absolute;
  height: 1px;
  left: 0;
  right: 100%;
  bottom: 0;
  background: var(--am-red);
  transition: right 0.3s ease;
}
.am-header nav a:hover::after,
.am-header nav a:focus-visible::after {
  right: 0;
}
/* Keep chapter surfaces below the fixed model and chapter content above it. */
.am-kicker,
.am-mono {
  font: 500 0.66rem var(--font-mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.am-kicker {
  color: var(--am-red);
  display: inline-flex;
  gap: 12px;
  align-items: center;
}
.am-kicker::before {
  content: "";
  width: 28px;
  height: 1px;
  background: var(--am-gold);
}
h1,
h2,
h3,
p {
  margin: 0;
}
h1 em,
h2 em {
  display: block;
  font-style: normal;
  color: var(--am-red);
}
h2 em {
  color: var(--am-indigo);
}
.am-structure {
  --am-section-background: color-mix(
    in srgb,
    var(--am-paper) 84%,
    var(--am-sakura)
  );
}
.am-light h2 em {
  color: var(--am-sakura);
}
.am-control {
  padding: 28px;
  border-left: 1px solid color-mix(in srgb, var(--am-paper) 35%, transparent);
  display: grid;
  gap: 18px;
  max-width: 420px;
}
.am-control label {
  font: 500 0.7rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.am-control output {
  float: right;
  color: var(--am-sakura);
}
.am-control input[type="range"] {
  width: 100%;
  accent-color: var(--am-sakura);
}
.am-parts button.is-active span {
  color: var(--am-red);
}
.am-parts button:focus-visible,
.am-swatches button:focus-visible,
.am-form input:focus-visible,
.am-button:focus-visible {
  outline: 2px solid var(--am-red);
  outline-offset: 4px;
}
.am-swatches button.is-active {
  border-color: var(--am-red);
  transform: translateX(10px);
}
.am-making li span {
  font: 500 0.63rem var(--font-mono);
  color: var(--am-red);
}
.am-making li strong {
  font: 500 1.25rem var(--font-display);
}
.am-commission h2 em {
  color: var(--am-sakura);
}
.am-commission dt,
.am-commission dd {
  margin: 0;
}
.am-commission dt {
  font: 500 0.58rem var(--font-mono);
  text-transform: uppercase;
  color: var(--am-sakura);
}
.am-commission dd {
  margin-top: 6px;
  font-size: 0.88rem;
}
/* The stage owns the composition; each chapter reserves its canvas rectangle. */
:root {
  --am-paper: #f4ecdd;
  --am-ink: #1a1613;
  --am-red: #c8412b;
  --am-indigo: #2b3a55;
  --am-gold: #b8923a;
  --am-sakura: #f2b8c6;
  --am-gutter: clamp(22px, 5vw, 82px);
  --am-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --am-ease-in-out: cubic-bezier(0.76, 0, 0.24, 1);
  --am-dur-1: 180ms;
  --am-dur-2: 360ms;
  --am-dur-3: 800ms;
  --am-dur-4: 1400ms;
}
html {
  background: var(--am-paper);
  scroll-behavior: auto;
  scrollbar-color: var(--am-gold) var(--am-paper);
}
::selection {
  background: var(--am-sakura);
  color: var(--am-ink);
}
input {
  caret-color: var(--am-sakura);
}
:focus-visible {
  outline: 2px solid var(--am-red);
  outline-offset: 5px;
}
h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 500;
  text-wrap: balance;
  letter-spacing: -0.04em;
}
p {
  max-width: 40ch;
  line-height: 1.65;
  font-size: clamp(1rem, 1.35vw, 1.2rem);
  text-wrap: pretty;
}
.am-page {
  position: relative;
  isolation: isolate;
  overflow: clip;
  background: transparent;
}
.am-world {
  position: fixed;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  background: var(--am-paper);
}
.am-washi {
  position: absolute;
  inset: 0;
  z-index: 2;
  mix-blend-mode: multiply;
}
.am-world__scene {
  position: absolute;
  inset: 0;
  opacity: var(--scene-opacity, 0);
}
.am-world__scene svg {
  width: 100%;
  height: 100%;
}
.am-world__scene[data-scene="0"] {
  --scene-opacity: 1;
}
.am-night,
.am-dusk {
  background: var(--am-indigo);
}
.am-blossoms {
  background: color-mix(in srgb, var(--am-sakura) 22%, var(--am-paper));
}
.am-drafting {
  background: color-mix(in srgb, var(--am-sakura) 10%, var(--am-paper));
}
.am-grove {
  background: var(--am-paper);
}
.am-ridge {
  transform: translateY(calc(var(--am-scene-progress, 0) * -24px));
}
.am-ridge--near {
  transform: translateY(calc(var(--am-scene-progress, 0) * -52px));
}
.am-mist {
  animation: am-mist 18s var(--am-ease-in-out) infinite alternate;
}
.am-petal {
  position: absolute;
  width: 16px !important;
  height: 22px !important;
  animation: am-petal 12s linear infinite;
}
.am-dye-blot {
  position: absolute;
  width: 50vw;
  height: 70vh;
  right: 0;
  top: 5vh;
  background: radial-gradient(ellipse, var(--am-dye) 0, transparent 65%);
  opacity: 0.1;
  transition: background var(--am-dur-3);
}
.am-rain-veil {
  position: absolute;
  inset: 0;
  overflow: hidden;
  opacity: var(--am-rain, 0);
}
.am-rain-veil i {
  position: absolute;
  top: -20%;
  width: 1px;
  height: 10%;
  background: color-mix(in srgb, var(--am-paper) 18%, transparent);
  animation: am-rain 1.2s linear infinite;
}
.am-puddle {
  transform-origin: 350px 850px;
  animation: am-puddle 3.2s var(--am-ease-out) infinite;
}
.am-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: clamp(18px, 4vw, 64px);
  padding: 18px var(--am-gutter);
  background: color-mix(in srgb, var(--am-paper) 88%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid color-mix(in srgb, var(--am-gold) 45%, transparent);
  transition: transform var(--am-dur-2) var(--am-ease-out);
  padding-block: 16px;
}
.am-header:focus-within {
  transform: none;
}
.am-header nav a[aria-current]::after {
  right: 0;
}
.am-header__counter {
  font: 400 0.62rem var(--font-mono);
  letter-spacing: 0.06em;
  color: var(--am-red);
  white-space: nowrap;
  overflow: hidden;
  font-variant-numeric: tabular-nums;
}
.am-header__counter b {
  display: inline-block;
  font-weight: 400;
  min-width: 2ch;
}
.am-sound {
  display: flex;
  gap: 8px;
  align-items: center;
  flex: none;
  padding: 8px 0;
  color: var(--am-indigo);
  background: none;
  border: 0;
  font: 400 0.6rem var(--font-mono);
  cursor: pointer;
}
.am-sound svg {
  width: 18px;
  height: 18px;
}
.am-sound[aria-pressed="true"] svg {
  color: var(--am-red);
}
.am-stage {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}
.am-canvas {
  position: absolute;
  inset: auto;
  left: 52vw;
  top: 12vh;
  width: 46vw;
  height: 80vh;
  opacity: 1;
  transform: none;
  pointer-events: auto;
  touch-action: pan-y;
}
.am-canvas canvas {
  display: block;
  width: 100%;
  height: 100%;
}
.am-poster {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.am-canvas[data-ready="true"] .am-poster {
  display: none;
}
.am-section {
  gap: clamp(32px, 8vw, 150px);
  position: relative;
  z-index: 2;
  min-height: 115svh;
  padding: clamp(120px, 18vh, 190px) var(--am-gutter);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  column-gap: 8vw;
  align-items: center;
  pointer-events: none;
}
.am-section::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--am-section-background, transparent);
  display: none;
}
.am-section > * {
  position: relative;
  z-index: 2;
  pointer-events: auto;
}
.am-section > .am-stage-anchor {
  position: absolute;
  top: 12svh;
  left: 51%;
  width: 48%;
  height: 80svh;
  pointer-events: none;
  z-index: -1;
}
.am-stage-anchor {
  visibility: hidden;
}
.am-chapter-copy {
  grid-column: 1;
  min-width: 0;
  max-width: 580px;
}
.am-structure .am-chapter-copy,
.am-making .am-chapter-copy,
.am-commission .am-chapter-copy {
  grid-column: 2;
}
.am-structure > .am-stage-anchor,
.am-making > .am-stage-anchor,
.am-commission > .am-stage-anchor {
  left: 0;
}
.am-hero {
  min-height: 100svh;
  padding-top: 160px;
}
.am-hero__copy {
  max-width: 500px;
}
h1 {
  letter-spacing: -0.06em;
  font-size: clamp(5rem, 10vw, 10rem);
  line-height: 0.95;
  margin: 28px 0;
}
h1 em {
  font: 400 clamp(1.1rem, 2.1vw, 2rem) var(--font-body);
  letter-spacing: -0.02em;
  font-size: clamp(1.35rem, 2vw, 2rem);
  line-height: 1.3;
  margin-top: 24px;
}
h2 {
  letter-spacing: -0.07em;
  font-size: clamp(3rem, 5.4vw, 5.5rem);
  line-height: 1.06;
  margin: 22px 0 26px;
}
.am-line {
  display: block;
  overflow: clip;
  padding-bottom: 0.12em;
  margin-bottom: -0.12em;
}
.am-line > span {
  display: block;
  will-change: transform;
}
.am-vertical {
  writing-mode: vertical-rl;
  position: absolute;
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 2vw, 2rem);
  letter-spacing: 0.2em;
  color: var(--am-indigo);
  top: 23vh;
  right: 30px;
  pointer-events: none;
}
.am-hero > .am-hanko {
  position: absolute;
  width: 52px;
  height: 52px;
  font-size: 0.72rem;
  bottom: 9vh;
  right: 7vw;
}
.am-stage-caption {
  position: absolute;
  right: var(--am-gutter);
  bottom: 7vh;
  font: 400 0.58rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--am-indigo);
}
.am-canopy .am-stage-caption {
  position: static;
  display: block;
  margin-top: 30px;
}
.am-light {
  --am-section-background: var(--am-indigo);
  color: var(--am-paper);
  min-height: 135svh;
  padding-top: 78svh;
  padding-bottom: 90px;
  align-items: start;
}
.am-light > .am-stage-anchor {
  top: 9svh;
  left: 14%;
  width: 72%;
  height: 59svh;
}
.am-light h2 {
  font-size: clamp(2.7rem, 4vw, 4rem);
}
.am-light .am-control {
  grid-column: 2;
  margin-top: 35px;
  width: 100%;
  justify-self: end;
}
.am-light .am-kicker {
  color: var(--am-sakura);
}
.am-parts {
  display: grid;
  gap: 0;
  margin-top: 30px;
  max-width: none;
}
.am-parts button {
  text-align: left;
  display: grid;
  border: 0;
  border-top: 1px solid color-mix(in srgb, var(--am-gold) 50%, transparent);
  background: none;
  color: inherit;
  cursor: pointer;
  position: relative;
  grid-template-columns: 1fr;
  overflow: hidden;
  padding: 16px 0;
  gap: 10px;
}
.am-parts button::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 1px;
  background: var(--am-gold);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-parts button:hover::before,
.am-parts button:focus-visible::before,
.am-parts button.is-active::before {
  transform: scaleX(1);
}
.am-parts button span {
  font: 500 0.74rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-parts button:hover span,
.am-parts button.is-active span {
  transform: translateX(10px);
}
.am-parts button i {
  font-style: normal;
  font-size: 0.8rem;
  text-align: left;
  min-height: 1.2em;
  color: var(--am-ink);
  opacity: 0.7;
  max-width: 42ch;
}
.am-parts button.is-active i {
  animation: am-detail var(--am-dur-2) var(--am-ease-out);
}
.am-leader {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: visible;
}
.am-leader path {
  fill: none;
  stroke: var(--am-gold);
  stroke-width: 1;
  stroke-dasharray: 900;
  stroke-dashoffset: 900;
  opacity: 0;
  transition:
    stroke-dashoffset var(--am-dur-3) var(--am-ease-out),
    opacity var(--am-dur-2);
}
.am-leader[data-active="true"] path {
  stroke-dashoffset: 0;
  opacity: 0.6;
}
.am-canopy {
  --am-section-background: color-mix(
    in srgb,
    var(--am-sakura) 24%,
    var(--am-paper)
  );
  min-height: 110svh;
}
.am-swatches {
  display: grid;
  margin-top: 36px;
  max-width: 380px;
  gap: 0;
  border-top: 1px solid var(--am-gold);
}
.am-swatches button {
  display: flex;
  align-items: center;
  gap: 14px;
  background: transparent;
  text-align: left;
  cursor: pointer;
  position: relative;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--am-gold) 40%, transparent);
  padding: 16px 5px;
  min-height: 64px;
  transform: none;
}
.am-swatches button span {
  border-radius: 50%;
  background: var(--swatch);
  border: 1px solid color-mix(in srgb, var(--am-ink) 25%, transparent);
  position: relative;
  flex: none;
  width: 30px;
  height: 30px;
}
.am-swatches button span::after {
  content: "";
  position: absolute;
  inset: -6px;
  border: 1px solid var(--am-red);
  border-radius: 50%;
  transform: rotate(-90deg) scale(0.8);
  opacity: 0;
  transition:
    transform var(--am-dur-2) var(--am-ease-out),
    opacity var(--am-dur-2);
}
.am-swatches button:hover span::after,
.am-swatches button.is-active span::after {
  transform: rotate(0) scale(1);
  opacity: 1;
}
.am-swatches button b {
  font: 400 0.8rem var(--font-body);
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-swatches button.is-active b {
  transform: translateX(6px);
}
.am-swatches button i {
  margin-left: auto;
  font-style: normal;
  opacity: 0;
}
.am-swatches button.is-active i {
  opacity: 1;
}
.am-making {
  --am-section-background: var(--am-paper);
  min-height: 155svh;
}
.am-making ol {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0 24px;
  border-top: 1px solid var(--am-gold);
  margin-top: 36px;
  grid-template-columns: 1fr;
}
.am-making li {
  display: flex;
  gap: 16px;
  align-items: baseline;
  padding: 16px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--am-gold) 45%, transparent);
  position: relative;
  transition:
    color var(--am-dur-2),
    transform var(--am-dur-2);
}
.am-making li::before {
  content: "";
  position: absolute;
  bottom: 0;
  height: 1px;
  width: 100%;
  background: var(--am-red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--am-dur-3) var(--am-ease-out);
}
.am-making li.is-current {
  color: var(--am-red);
  transform: translateX(5px);
}
.am-making li.is-current::before {
  transform: scaleX(1);
}
.am-commission {
  --am-section-background: var(--am-indigo);
  color: var(--am-paper);
  min-height: 145svh;
}
.am-commission .am-kicker {
  color: var(--am-sakura);
}
.am-commission h2 {
  font-size: clamp(2.6rem, 4.5vw, 4.8rem);
}
.am-commission dl {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  border-top: 1px solid color-mix(in srgb, var(--am-paper) 24%, transparent);
  padding-top: 18px;
  margin-top: 25px;
  margin-bottom: 30px;
}
.am-form {
  display: grid;
  padding: 0;
  border: 0;
  background: none;
  gap: 20px;
}
.am-form label {
  font: 500 0.65rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding-top: 14px;
}
.am-form label span {
  position: absolute;
  top: 30px;
  left: 0;
  pointer-events: none;
  transition:
    transform var(--am-dur-2) var(--am-ease-out),
    color var(--am-dur-2);
}
.am-form label:focus-within span,
.am-form label:has(input:not(:placeholder-shown)) span {
  transform: translateY(-23px) scale(0.85);
  transform-origin: left;
  color: var(--am-sakura);
}
.am-form label::after {
  content: "";
  position: absolute;
  left: 0;
  top: 54px;
  width: 100%;
  height: 1px;
  background: var(--am-sakura);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-form label:focus-within::after {
  transform: scaleX(1);
}
.am-form input {
  width: 100%;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--am-paper) 40%, transparent);
  padding: 10px 0;
  background: transparent;
  color: var(--am-paper);
  outline: none;
  min-height: 42px;
  border-radius: 0;
}
.am-form input[aria-invalid="true"] {
  border-color: var(--am-sakura);
}
.am-form small {
  color: var(--am-sakura);
  margin-top: 8px;
  animation: am-nudge var(--am-dur-2);
}
.am-success {
  padding: 32px 0;
}
.am-success > .am-hanko {
  width: 64px;
  height: 64px;
  animation: am-stamp 0.6s var(--am-ease-out);
}
.am-success h3 {
  margin: 20px 0;
  font-size: 2.5rem;
}
.am-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-width: 210px;
  margin-top: 32px;
  padding: 14px 16px;
  border: 1px solid var(--am-ink);
  font: 500 0.68rem var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  background: transparent;
  cursor: pointer;
  transform: none;
  transition: color var(--am-dur-2);
}
.am-button::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  background: var(--am-red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-button--red {
  border-color: var(--am-red);
  color: var(--am-paper);
  background: var(--am-red);
}
.am-button--red::before {
  background: var(--am-ink);
}
.am-button:hover::before {
  transform: scaleX(1);
}
.am-button:hover {
  transform: none;
  color: var(--am-paper);
}
.am-button:active {
  transform: scale(0.97);
  scale: 0.98;
}
.am-button > span {
  transform: translate(var(--magnet-x, 0px), var(--magnet-y, 0px));
  transition: transform var(--am-dur-2) var(--am-ease-out);
}
.am-button:hover > span {
  animation: am-arrow var(--am-dur-2) var(--am-ease-out);
}
.am-press-ripple {
  position: absolute;
  width: 8px;
  height: 8px;
  margin: -4px;
  border: 1px solid var(--am-paper);
  border-radius: 50%;
  pointer-events: none;
  animation: am-click 0.65s var(--am-ease-out) forwards;
}
input[type="range"] {
  min-height: 32px;
  cursor: ew-resize;
  accent-color: var(--am-sakura);
}
input[type="range"]::-webkit-slider-thumb {
  transition: transform var(--am-dur-1);
}
input[type="range"]:active::-webkit-slider-thumb {
  transform: scale(1.3);
}
.am-switch {
  display: flex;
  align-items: center;
  gap: 12px;
  position: relative;
  cursor: pointer;
  text-transform: none !important;
}
.am-switch input {
  accent-color: var(--am-red);
  position: absolute;
  width: 42px;
  height: 28px;
  opacity: 0;
  cursor: pointer;
}
.am-switch__pour {
  pointer-events: none;
  position: relative;
  width: 42px;
  height: 24px;
  border: 1px solid var(--am-sakura);
  border-radius: 20px;
  flex: none;
}
.am-switch__pour::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--am-sakura);
  transition:
    transform var(--am-dur-2) var(--am-ease-out),
    border-radius var(--am-dur-2);
}
.am-switch:has(input:checked) .am-switch__pour::after {
  transform: translateX(18px) rotate(45deg);
  border-radius: 50% 50% 50% 0;
}
.am-switch:has(input:focus-visible) .am-switch__pour {
  pointer-events: none;
  outline: 2px solid var(--am-sakura);
  outline-offset: 4px;
}
.am-cursor {
  display: none;
}
.am-footer {
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 28px var(--am-gutter);
  background: var(--am-ink);
  color: var(--am-paper);
  font: 500 0.62rem var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  position: relative;
  min-height: 160px;
  padding-block: 55px;
}
.am-footer > .am-hanko {
  width: 40px;
  height: 40px;
}
@keyframes am-mist {
  to {
    transform: translateX(5%);
  }
}
@keyframes am-petal {
  to {
    transform: translate(70px, 90px) rotate(220deg);
  }
}
@keyframes am-rain {
  to {
    transform: translate(-60px, 130vh);
  }
}
@keyframes am-puddle {
  0% {
    transform: scale(0.6);
    opacity: 0;
  }
  30% {
    opacity: 0.4;
  }
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}
@keyframes am-detail {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
}
@keyframes am-nudge {
  25% {
    transform: translateX(5px);
  }
  70% {
    transform: translateX(-2px);
  }
}
@keyframes am-stamp {
  from {
    opacity: 0;
    transform: translateY(-25px) rotate(-14deg) scale(1.4);
  }
}
@keyframes am-arrow {
  45% {
    transform: translate(16px, -16px);
    opacity: 0;
  }
  46% {
    transform: translate(-16px, 16px);
  }
}
@keyframes am-click {
  to {
    transform: scale(30);
    opacity: 0;
  }
}
@media (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .am-cursor {
    display: block;
    position: fixed;
