}

/* Cinematic enhancement: one set of viewport reservations for copy, tools and navigation. */
.am-page {
  --am-header-h: 76px;
  --am-journey-nav-h: 76px;
  --am-making-strip-h: 76px;
  --am-nav-bottom: 20px;
  --am-ui-gap: 12px;
  --am-stage-h: 36svh;
  --am-copy-top: calc(
    var(--am-header-h) + 8px + var(--am-stage-h) + var(--am-ui-gap)
  );
  --am-nav-clearance: calc(
    var(--am-journey-nav-h) + var(--am-nav-bottom) + var(--am-ui-gap)
  );
  background: var(--page-bg, var(--am-paper));
}
.am-header {
  height: var(--am-header-h);
  padding: 8px var(--am-gutter);
  gap: 20px;
  z-index: 50;
}
.am-header .am-logo {
  flex: none;
  min-width: 44px;
  min-height: 44px;
}
.am-header .am-hanko {
  font-size: 11px;
}
.am-scroll-cue {
  display: none;
}
.am-page[data-world-mode="cinematic"] .am-button {
  font-size: 11px;
}
.am-header .am-time {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  gap: 6px;
  min-width: 0;
  width: min(420px, 100%);
  max-width: 420px;
  flex: 1;
  margin: 0 auto;
}
.am-time label {
  min-width: 0;
  font: 400 11px/14px var(--font-mono);
  color: inherit;
}
.am-time label > span {
  display: flex;
  justify-content: space-between;
  margin: 0;
  white-space: nowrap;
}
.am-time input {
  display: block;
  width: 100%;
  min-width: 0;
  height: 44px;
  margin: 0;
  accent-color: var(--am-gold);
}
.am-time button {
  min-width: 44px;
  min-height: 44px;
  padding: 0 4px;
  border: 0;
  background: none;
  color: inherit;
  font: 400 11px var(--font-mono);
  cursor: pointer;
}
.am-header .am-sound {
  min-height: 44px;
  min-width: 44px;
  padding: 0 8px;
  color: inherit;
  font-size: 11px;
}
.am-header__counter {
  font-size: 11px;
}
.am-static-poster {
  position: absolute;
  right: 3%;
  top: 18svh;
  width: 42%;
  height: 65svh;
  max-height: 65svh;
}
.am-static-poster svg {
  width: 100%;
  height: 100%;
}
.am-page[data-world-mode="static"] .am-stage {
  position: absolute;
  bottom: auto;
  height: 100svh;
  z-index: 3;
}
.am-page:not([data-world-mode="cinematic"]) .am-inspector-detail {
  display: none;
}
.am-page[data-world-mode="static"] .am-anatomy-fallback {
  display: grid;
}
.am-page[data-world-mode="static"] .am-section::before {
  display: block;
}
.am-page[data-world-mode="static"] .am-line > span {
  opacity: 1 !important;
  transform: none !important;
}
.am-page[data-world-mode="static"] {
  color: var(--text-contrast);
}
.am-page[data-world-mode="static"] .am-header {
  background: var(--page-bg);
  color: var(--text-contrast);
}
.am-page[data-world-mode="static"] .am-section {
  --am-section-background: var(--page-bg);
  color: var(--text-contrast);
}
.am-page[data-world-mode="static"]
  :is(
    h1 em,
    h2 em,
    .am-kicker,
    .am-sound,
    .am-header__counter,
    .am-inspector-spec,
    .am-stage-caption,
    .am-making li span,
    .am-control output,
    .am-commission dt,
    .am-form input,
    .am-form small
  ) {
  color: inherit;
}
.am-page[data-world-mode="static"] .am-form input {
  border-color: currentColor;
}
.am-page[data-world-mode="static"] .am-header {
  flex-wrap: wrap;
  height: auto;
  min-height: var(--am-header-h);
}
.am-page[data-world-mode="static"] .am-header nav {
  display: flex;
  flex: 0 0 100%;
  justify-content: center;
  gap: 8px 20px;
  flex-wrap: wrap;
  font: 400 11px var(--font-mono);
}
.am-page[data-world-mode="static"] .am-header nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 6px;
}
.am-page[data-world-mode="static"] .am-section {
  scroll-margin-top: 150px;
}
.am-page[data-world-mode="static"] .am-static-poster {
  top: 150px;
}
.am-loading {
  position: fixed;
  inset: auto 0 8svh;
  z-index: 70;
  text-align: center;
  pointer-events: none;
  font: 400 11px var(--font-mono);
  color: var(--am-ink);
}
.am-loading span {
  display: block;
  font: 400 2rem var(--font-display);
  margin-top: 10px;
}
.am-page[data-world-mode="loading"] .am-canvas {
  visibility: hidden;
}
.am-page[data-world-mode="cinematic"] {
  --am-world-text: var(--am-paper);
  color: var(--am-world-text);
  background: transparent;
}
.am-page[data-world-mode="cinematic"][data-paper-lit="true"] {
  --am-world-text: var(--am-ink);
}
.am-world-track {
  height: 900svh;
  pointer-events: none;
}
.am-page[data-world-mode="cinematic"] .am-world {
  display: none;
}
.am-page[data-world-mode="cinematic"] > .am-footer {
  display: none;
}
.am-page[data-world-mode="cinematic"] > .am-section,
.am-page[data-world-mode="cinematic"] > #making {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100svh;
  min-height: 0;
  z-index: 4;
  opacity: var(--chapter-opacity, 0);
  pointer-events: none;
  overflow: hidden;
  padding: calc(var(--am-header-h) + 20px) var(--am-gutter)
    var(--am-nav-clearance);
  color: inherit;
  background: none;
}
.am-page[data-world-mode="cinematic"] > #making {
  padding: 0;
}
.am-page[data-world-mode="cinematic"] .am-making-frame {
  position: static;
  height: 100svh;
  min-height: 0;
  padding: calc(var(--am-header-h) + 20px) var(--am-gutter)
    calc(var(--am-nav-clearance) + var(--am-making-strip-h) + 68px);
}
.am-page[data-world-mode="cinematic"] .am-section::before {
  display: none;
}
.am-page[data-world-mode="cinematic"] .am-chapter-copy {
  display: block;
  --am-world-text: var(--am-paper);
  color: var(--am-paper);
  background: linear-gradient(
    90deg,
    rgba(26, 22, 19, 0.78),
    rgba(26, 22, 19, 0.66)
  );
  max-height: calc(
    100svh - var(--am-header-h) - var(--am-nav-clearance) - 32px
  );
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--am-gold) transparent;
  pointer-events: auto;
  align-self: center;
  overscroll-behavior: contain;
  padding: 24px;
}
.am-page[data-world-mode="cinematic"] .am-chapter-copy > p {
  font-size: clamp(0.9rem, 1.1vw, 1.1rem);
  max-width: 44ch;
}
.am-page[data-world-mode="cinematic"] .am-line > span {
  transform: translateY(var(--chapter-rise, 0%)) !important;
  opacity: 1 !important;
}
.am-page[data-world-mode="cinematic"] .am-light {
  display: block;
}
.am-page[data-world-mode="cinematic"] .am-light .am-chapter-copy {
  position: absolute;
  bottom: var(--am-nav-clearance);
  left: var(--am-gutter);
  width: min(36vw, 490px);
}
.am-page[data-world-mode="cinematic"]
  :is(
    .am-light .am-control,
    .am-making ol,
    .am-making-guide,
    .am-stage-caption,
    .am-vertical,
    .am-hero > .am-hanko
  ) {
  display: none;
}
.am-page[data-world-mode="cinematic"] .am-header {
  background: rgba(26, 22, 19, 0.86);
  color: var(--am-world-text);
}
.am-page[data-world-mode="cinematic"][data-paper-lit="true"] .am-header {
  background: rgba(244, 236, 221, 0.94);
}
.am-page[data-world-mode="cinematic"] .am-kicker {
  font-size: 11px;
  line-height: 1.4;
  color: var(--am-world-text);
  opacity: 0.85;
}
.am-page[data-world-mode="cinematic"] .am-chapter-copy h1 em {
  color: var(--am-sakura);
}
.am-page[data-world-mode="cinematic"]
  :is(h2, h2 em, .am-inspector-spec, .am-sound, .am-swatches button) {
  color: inherit;
}
.am-page[data-world-mode="cinematic"][data-paper-lit="false"]
  .am-header__counter {
  color: var(--am-sakura);
}
.am-journey-nav {
  position: fixed;
  left: var(--am-gutter);
  right: var(--am-gutter);
  bottom: var(--am-nav-bottom);
  z-index: 20;
  min-height: var(--am-journey-nav-h);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border-top: 1px solid color-mix(in srgb, currentColor 30%, transparent);
  pointer-events: auto;
  background: rgba(26, 22, 19, 0.82);
  color: var(--am-world-text);
}
.am-page[data-paper-lit="true"] .am-journey-nav {
  background: rgba(244, 236, 221, 0.94);
}
.am-journey-nav > button {
  min-width: 44px;
  min-height: 44px;
  display: inline-grid;
  place-items: center;
  background: none;
  border: 0;
  color: inherit;
  font-size: 1.3rem;
  padding: 0;
  cursor: pointer;
}
.am-journey-nav button:disabled {
  opacity: 0.3;
  cursor: default;
}
.am-chapter-marker {
  flex: 1;
  min-width: 0;
  font: 400 11px/1.4 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.am-chapter-marker small {
  display: block;
  font-size: 11px;
  opacity: 0.82;
  margin-top: 4px;
  letter-spacing: 0;
}
.am-jump-list {
  display: flex;
  gap: 4px;
}
.am-jump-list button {
  min-width: 44px;
  min-height: 44px;
  position: relative;
  border: 0;
  border-bottom: 1px solid transparent;
  background: none;
  color: inherit;
  font: 400 11px var(--font-mono);
  padding: 0 8px;
  cursor: pointer;
  opacity: 0.75;
}
.am-jump-list button[aria-current] {
  opacity: 1;
  border-color: currentColor;
}
.am-jump-list button[data-sub-rest]::before,
.am-jump-list button[data-sub-rest]::after {
  content: "";
  position: absolute;
  bottom: 5px;
  width: 4px;
  height: 4px;
  border: 1px solid currentColor;
  border-radius: 50%;
}
.am-jump-list button[data-sub-rest]::before {
  left: calc(50% - 6px);
}
.am-jump-list button[data-sub-rest]::after {
  left: calc(50% + 2px);
}
.am-jump-list button[data-sub-rest="calm"]::before,
.am-jump-list button[data-sub-rest="street"]::after {
  background: currentColor;
}
.am-enter-tool {
  position: fixed;
  right: var(--am-gutter);
  bottom: calc(var(--am-nav-clearance) + 16px);
  z-index: 15;
  min-height: 44px;
  border: 1px solid currentColor;
  background: rgba(26, 22, 19, 0.88);
  color: var(--am-paper);
  padding: 12px 20px;
  font: 400 11px var(--font-mono);
  cursor: pointer;
}
.am-enter-tool span {
  margin-left: 20px;
}
.am-page[data-active-chapter="4"] .am-enter-tool {
  bottom: calc(var(--am-nav-clearance) + var(--am-making-strip-h) + 20px);
}
.am-making-strip {
  position: fixed;
  left: var(--am-gutter);
  right: var(--am-gutter);

  bottom: var(--am-nav-clearance);
  z-index: 15;
  height: var(--am-making-strip-h);
  display: flex;
  overflow: auto hidden;
  overscroll-behavior: contain;
  gap: 0;
  border-top: 1px solid var(--am-gold);
  background: rgba(244, 236, 221, 0.96);
  color: var(--am-ink);
  padding: 8px 10px;
  scrollbar-width: thin;
  scrollbar-color: var(--am-gold) transparent;
}
.am-making-strip button {
  min-width: 110px;
  flex: 1;
  min-height: 44px;
  padding: 0 8px;
  background: none;
  border: 0;
  color: inherit;
  text-align: left;
  font: 400 11px/1.3 var(--font-mono);
  opacity: 0.8;
  cursor: pointer;
}
.am-making-strip button span {
  display: block;
  font-size: 11px;
  margin-bottom: 4px;
}
.am-making-strip button[aria-current] {
  opacity: 1;
  color: var(--am-red);
}
.am-tool-sheet {
  position: fixed;
  right: var(--am-gutter);
  top: calc(var(--am-header-h) + 16px);
  bottom: var(--am-nav-clearance);
  width: min(38vw, 500px);
  z-index: 40;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--am-gold) transparent;
  background: var(--am-paper);
  color: var(--am-ink);
  padding: 24px;
  border-top: 1px solid var(--am-gold);
  box-shadow: 0 18px 50px rgba(26, 22, 19, 0.12);
}
.am-tool-sheet > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font: 400 11px var(--font-mono);
  padding-bottom: 12px;
  border-bottom: 1px solid var(--am-gold);
}
.am-tool-sheet h3 {
  font: 400 1.7rem var(--font-display);
  margin: 20px 0 12px;
}
.am-tool-sheet p {
  font-size: 0.9rem;
  line-height: 1.6;
}
.am-tool-sheet button {
  background: none;
  border: 0;
  color: inherit;
  cursor: pointer;
  min-height: 44px;
  font-size: 11px;
}
.am-tool-sheet label {
  display: block;
  margin-top: 20px;
  font: 400 11px var(--font-mono);
}
.am-tool-sheet input[type="range"] {
  display: block;
  width: 100%;
  min-height: 44px;
  margin-top: 8px;
  accent-color: var(--am-red);
}
.am-tool-sheet .am-inspector-detail {
  display: block;
  border: 0;
  padding: 16px 0 0;
}
.am-tool-sheet .am-inspector-actions {
  margin: 12px 0;
}
.am-tool-sheet .am-inspector-material,
.am-tool-sheet .am-inspector-runner,
.am-tool-sheet .am-inspector-runner small {
  font-size: 11px;
}
.am-tool-close {
  font: 400 11px var(--font-mono);
  padding: 0;
  white-space: nowrap;
}
.am-tool-close span {
  font-size: 1.3rem;
  margin-left: 12px;
}
.am-focus-stage {
  font: 400 11px var(--font-mono);
  margin: 12px 0;
}
.am-sheet-parts {
  display: none;
}
@media (min-width: 901px) and (max-height: 840px) {
  .am-tool-sheet {
    top: calc(var(--am-header-h) + 6px);
    bottom: calc(var(--am-journey-nav-h) + 20px);
    padding: 14px 18px;
  }
  .am-tool-sheet > header {
    padding-bottom: 6px;
  }
  .am-tool-sheet h3 {
    font-size: 1.35rem;
    margin: 8px 0 4px;
  }
  .am-tool-sheet p {
    font-size: 0.85rem;
    line-height: 1.4;
  }
  .am-tool-sheet .am-inspector-detail {
    padding-top: 6px;
  }
  .am-tool-sheet label {
    margin-top: 8px;
  }
  .am-tool-sheet .am-inspector-runner {
    margin-top: 8px;
  }
  .am-tool-sheet .am-inspector-actions {
    margin: 6px 0;
  }
  .am-focus-stage {
    margin: 6px 0;
  }
}
.am-page:not([data-tool="none"]) .am-journey-nav {
  opacity: 0.35;
  pointer-events: none;
}
.am-page:not([data-tool="none"]) .am-chapter-copy {
  visibility: hidden;
  pointer-events: none;
}
.am-page[data-tool="making"] .am-tool-sheet {
  bottom: calc(var(--am-nav-clearance) + var(--am-making-strip-h) + 12px);
}
.am-canvas:focus-visible {
  outline: 2px solid var(--am-gold);
  outline-offset: -5px;
}
.am-inspector-navigation__foot,
.am-inspector-navigation__foot button,
.am-inspector-parts.am-parts button small,
.am-inspector-parts.am-parts button span,
.am-tool-sheet .am-inspector-range-ends,
.am-hotspot b {
  font-size: 11px;
}
.am-page[data-world-mode="cinematic"] .am-inspector-navigation {
  color: var(--am-ink);
}
.am-hotspot {
  min-width: 44px;
  min-height: 44px;
}
.am-hotspot span {
  font-size: 11px;
}
.am-inspector-navigation__foot button {
  min-height: 44px;
}
.am-page[data-world-mode="cinematic"] > .am-commission {
  padding-top: calc(var(--am-header-h) + 8px);
}
.am-page[data-world-mode="cinematic"] .am-commission .am-chapter-copy {
  max-height: calc(
    100svh - var(--am-header-h) - var(--am-nav-clearance) - 12px
  );
}
.am-page[data-world-mode="cinematic"] .am-commission h2 {
  font-size: clamp(2.2rem, 3.6vw, 3.6rem);
  margin: 10px 0 14px;
}
.am-page[data-world-mode="cinematic"] .am-commission dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 12px 0 16px;
  padding-top: 12px;
  gap: 10px;
}
.am-page[data-world-mode="cinematic"] .am-commission dt {
  font-size: 11px;
}
.am-page[data-world-mode="cinematic"] .am-commission dd {
  font-size: 14px;
  line-height: 1.4;
}
.am-page[data-world-mode="cinematic"] .am-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.am-page[data-world-mode="cinematic"] .am-form label:last-of-type,
.am-page[data-world-mode="cinematic"] .am-form :is(button, noscript) {
  grid-column: 1/-1;
}
.am-page[data-world-mode="cinematic"] .am-form label {
  padding-top: 0;
  min-width: 0;
  font-size: 11px;
}
.am-page[data-world-mode="cinematic"] .am-form label span {
  top: 16px;
}
.am-page[data-world-mode="cinematic"] .am-form input {
  min-height: 44px;
  padding: 16px 0 4px;
  font-size: 16px;
  line-height: 20px;
}
.am-page[data-world-mode="cinematic"] .am-form label:focus-within span,
.am-page[data-world-mode="cinematic"]
  .am-form
  label:has(input:not(:placeholder-shown))
  span {
  transform: translateY(-16px) scale(0.9);
}
.am-page[data-world-mode="cinematic"] .am-form label::after {
  top: auto;
  bottom: 0;
}
.am-page[data-world-mode="cinematic"] .am-form .am-button {
  min-height: 44px;
  min-width: 0;
  margin-top: 12px;
  padding: 10px 14px;
}
@media (min-width: 901px) {
  .am-page[data-world-mode="cinematic"] .am-commission .am-chapter-copy > p {
    font-size: 16px;
    line-height: 1.5;
  }
  .am-page[data-world-mode="cinematic"] .am-canopy .am-swatches {
    margin-top: 24px;
  }
  .am-page[data-world-mode="cinematic"] .am-canopy .am-swatches button {
    min-height: 56px;
    padding-block: 12px;
  }
}
@media (max-width: 1100px) {
  .am-header__counter {
    display: none;
  }
}
@media (max-width: 900px) {
  .am-page {
    --am-nav-bottom: 10px;
    --am-journey-nav-h: 76px;
    --am-nav-clearance: 98px;
    --am-gutter: 16px;
  }
  .am-header {
    padding: 8px 12px;
    gap: 8px;
  }
  .am-header .am-time {
    gap: 0;
  }
  .am-header .am-sound span {
    display: none;
  }
  .am-header .am-sound svg {
    width: 18px;
    height: 18px;
  }
  .am-journey-nav {
    left: 8px;
    right: 8px;
    padding: 6px 4px;
    gap: 0;
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr) 44px;
    grid-template-rows: 16px 44px;
  }
  .am-chapter-marker {
    grid-column: 1/-1;
    grid-row: 1;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .am-chapter-marker small {
    display: inline;
    margin: 0;
    font-size: 11px;
    white-space: nowrap;
  }
  .am-jump-list {
    grid-column: 2;
    grid-row: 2;
    display: flex;
    justify-content: center;
    gap: 0;
    min-width: 0;
    width: 100%;
  }
  .am-jump-list button {
    flex: 1 1 0;
    min-width: 44px;
    min-height: 44px;
    padding: 0;
  }
  @media (max-width: 374px) {
    .am-jump-list button {
      min-width: 32px;
    }
  }
  .am-journey-nav > button {
    grid-row: 2;
  }
  .am-journey-nav > button:last-child {
    grid-column: 3;
  }
  .am-page[data-world-mode="cinematic"] > .am-section,
  .am-page[data-world-mode="cinematic"] .am-making-frame {
    display: block;
    padding: var(--am-copy-top) 16px var(--am-nav-clearance);
  }
  .am-page[data-world-mode="cinematic"] .am-chapter-copy {
    width: 100%;
    max-width: none;
